:root{--bg:#07111e;--panel:#0d1c30;--panel2:#12233b;--line:#1f3555;--text:#e6edf7;--dim:#c7d6ec;--faint:#9cb0cf;--accent:#7c9eff;--sw:290px}
*{box-sizing:border-box}html{scroll-behavior:smooth;overflow-x:hidden}
body{margin:0;background:var(--bg);color:var(--text);font-family:"Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic",Meiryo,"Noto Sans CJK JP",sans-serif;line-height:1.85;font-size:16px;overflow-x:hidden}
.sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--sw);background:var(--panel);border-right:1px solid var(--line);overflow-y:auto;padding:22px 16px;z-index:20}
.sidebar .brand{font-size:13px;color:var(--accent);font-weight:700;letter-spacing:.04em;margin-bottom:14px}
.sidebar ul{list-style:none;margin:0;padding:0}.sidebar a{display:block;padding:7px 10px;border-radius:8px;color:var(--dim);text-decoration:none;font-size:13.5px;line-height:1.45}
.sidebar a:hover{background:var(--panel2)}.sidebar a.active{background:rgba(124,158,255,.16);color:#fff;border-left:3px solid var(--accent)}
.toggle{display:none;position:fixed;top:12px;left:12px;z-index:30;background:var(--accent);color:#07111e;border:0;border-radius:8px;padding:8px 12px;font-weight:700}
.main{margin-left:var(--sw);padding:40px 48px 80px}
.hero{position:relative;background:linear-gradient(180deg,#0d1c30,#0a1626);border:1px solid var(--line);border-radius:16px;padding:32px;margin-bottom:36px;overflow:hidden}
.hero::before{content:"";position:absolute;top:-80px;right:-80px;width:320px;height:320px;background:radial-gradient(circle,rgba(124,158,255,.25),transparent 70%)}
.eyebrow{display:inline-block;font-size:12px;font-weight:700;color:var(--accent);border:1px solid var(--accent);border-radius:999px;padding:3px 12px;margin-bottom:12px}
.hero h1{position:relative;margin:0 0 20px;font-size:28px;font-weight:800;color:#fff;line-height:1.4}
.meta{position:relative;display:flex;flex-wrap:wrap;gap:0}.meta-item{padding:4px 22px 4px 0;margin-right:22px;border-right:1px solid var(--line);max-width:100%}
.meta-item:last-child{border-right:0}.meta-item span{display:block;font-size:11px;color:var(--faint);text-transform:uppercase}.meta-item b{font-size:14.5px;font-weight:500;color:var(--text);overflow-wrap:anywhere}
h2{font-size:24px;color:#fff;margin:56px 0 14px;padding-bottom:10px;border-bottom:2px solid var(--line);scroll-margin-top:16px}
h3{font-size:19px;color:var(--accent);margin:34px 0 10px}h4{font-size:16.5px;color:#fff;margin:26px 0 8px}
p,li{color:var(--text)}a{color:var(--accent);overflow-wrap:anywhere}strong{color:#fff}
code{background:var(--panel2);padding:2px 6px;border-radius:5px;font-size:.92em;overflow-wrap:anywhere}
.table-scroll{overflow-x:auto;margin:16px 0;border:1px solid var(--line);border-radius:10px}
table{border-collapse:collapse;width:100%;min-width:520px;font-size:14.5px}th{background:var(--panel2);color:#fff;text-align:left}
th,td{padding:10px 14px;border-bottom:1px solid var(--line);vertical-align:top}tr:last-child td{border-bottom:0}
blockquote{margin:18px 0;padding:12px 18px;border-left:4px solid var(--accent);background:var(--panel);border-radius:0 10px 10px 0}blockquote p{margin:6px 0}
.callout-practice{margin:18px 0;padding:14px 18px;background:rgba(124,158,255,.10);border:1px solid rgba(124,158,255,.4);border-radius:12px}
.glossary{margin:26px 0 8px;padding:14px 18px;background:var(--panel);border:1px solid var(--line);border-radius:12px}.glossary p{margin:0 0 6px;font-weight:700;color:#fff}.glossary ul{margin:0;padding-left:20px;color:var(--dim)}.glossary li{color:var(--dim);font-size:14.5px}
.mermaid-diagram{display:block;overflow-x:auto;margin:20px 0;padding:18px;background:var(--panel);border:1px solid var(--line);border-radius:12px}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none;flex-shrink:0}
.mermaid-diagram p{color:inherit;margin:0}

.check-overall{position:sticky;top:8px;z-index:5;margin:18px 0;padding:14px 18px;background:rgba(13,28,48,.96);border:1px solid var(--accent);border-radius:14px;backdrop-filter:blur(6px)}
.ov-top{display:flex;align-items:center;gap:14px}.ov-top b{flex:1;color:#fff}.ov-count{font-size:14px;color:var(--accent);font-weight:700;font-variant-numeric:tabular-nums}
.ov-reset{background:transparent;border:1px solid var(--line);color:var(--faint);border-radius:8px;padding:4px 12px;font-size:12.5px;cursor:pointer}.ov-reset:hover{color:#fff;border-color:var(--accent)}
.check-card{background:var(--panel);border:1px solid var(--line);border-radius:14px;margin:18px 0;padding:16px 18px 10px}
.check-head{display:flex;align-items:center;gap:12px}.check-badge{width:30px;height:30px;border-radius:9px;background:rgba(124,158,255,.18);color:var(--accent);display:grid;place-items:center;font-weight:800;flex:none}
.check-head h4{margin:0;flex:1;font-size:16px;color:#fff}.check-count{font-size:13px;color:var(--faint);font-variant-numeric:tabular-nums}
.check-bar{height:6px;background:var(--panel2);border-radius:99px;margin:12px 0 8px;overflow:hidden}.check-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#5b7cff,#7c9eff);transition:width .25s}
.check-card.complete{border-color:#3ecf8e}.check-card.complete .check-badge{background:rgba(62,207,142,.18);color:#3ecf8e}.check-card.complete .check-bar i{background:#3ecf8e}
ul.checklist{list-style:none;margin:0;padding:0}ul.checklist li{margin:0}
ul.checklist label{display:flex;gap:14px;align-items:flex-start;padding:11px 12px;border-radius:10px;cursor:pointer;transition:background .15s}ul.checklist label:hover{background:rgba(124,158,255,.08)}
ul.checklist input[type=checkbox]{appearance:none;-webkit-appearance:none;flex:none;width:22px;height:22px;margin:3px 0 0;border:2px solid #4a6592;border-radius:7px;background:var(--bg);display:grid;place-content:center;cursor:pointer;transition:background .15s,border-color .15s}
ul.checklist input[type=checkbox]::after{content:"";width:6px;height:11px;border:solid #07111e;border-width:0 2.5px 2.5px 0;transform:rotate(45deg) scale(0);margin-top:-2px;transition:transform .15s}
ul.checklist input[type=checkbox]:checked{background:var(--accent);border-color:var(--accent)}ul.checklist input[type=checkbox]:checked::after{transform:rotate(45deg) scale(1)}
ul.checklist input[type=checkbox]:focus-visible{outline:2px solid #fff;outline-offset:2px}
ul.checklist .txt{line-height:1.7}ul.checklist li.done .txt{color:var(--faint);text-decoration:line-through;text-decoration-color:rgba(156,176,207,.5)}

.footer{margin-top:60px;padding-top:18px;border-top:1px solid var(--line);color:var(--faint);font-size:13px}
@media(max-width:900px){.sidebar{transform:translateX(-100%);transition:.2s}.sidebar.open{transform:none}.toggle{display:block}.main{margin-left:0;padding:64px 16px 60px}.meta-item{border-right:0;border-bottom:1px solid var(--line);width:100%;margin:0 0 8px}}
